      TYPE POLYGON
     # LABELITEM "Comuna"
        CLASS
		#NAME "LABEL"
            STYLE
              COLOR 230 233 234
              OUTLINECOLOR 0 0 0
            END
		#	LABEL
		#	SIZE SMALL
		#	COLOR 0 0 0
		#	END
    END
   END

  LAYER
      NAME "One"
